  const dictionary={};
  for(const [es,en] of Object.entries(english))dictionary[es]={es,en};
  Object.assign(dictionary,{
    open:{es:'Abierto',en:'Open'},contracted:{es:'Contratado',en:'Contracted'},closed:{es:'Cerrado',en:'Closed'},completed:{es:'Finalizado',en:'Completed'},suspended:{es:'Suspendido',en:'Suspended'},submitted:{es:'Enviada',en:'Submitted'},accepted:{es:'Aceptada',en:'Accepted'},rejected:{es:'Rechazada',en:'Rejected'},withdrawn:{es:'Retirada',en:'Withdrawn'},pending:{es:'Pendiente',en:'Pending'},verified:{es:'Verificada',en:'Verified'},resolved:{es:'Resuelto',en:'Resolved'},dismissed:{es:'Descartado',en:'Dismissed'}
  });
  const aliases=new Map();
  for(const [key,value] of Object.entries(dictionary)){aliases.set(key,key);aliases.set(value.es,key);aliases.set(value.en,key)}
  const normalize=value=>String(value??'').replace(/\s+/g,' ').trim();
  const requestedLanguage=new URLSearchParams(location.search).get('lang');
  let language=requestedLanguage==='en'||requestedLanguage==='es'?requestedLanguage:(localStorage.getItem('cm_language')==='en'?'en':'es');
  if(requestedLanguage==='en'||requestedLanguage==='es')localStorage.setItem('cm_language',requestedLanguage);
  function pattern(value,target){
    const pairs=target==='en'?[ [/^Hola, (.+)\.$/,'Hello, $1.'], [/^(\d+) cotizaciones recibidas$/,'$1 quotes received'], [/^Cotizar: (.+)$/,'Quote: $1'], [/^Actualizado (.+)$/,'Updated $1'], [/^Reporte sobre (.+)$/,'Report about $1'], [/^Reportado por @(.+)$/,'Reported by @$1'], [/(\d+) días\b/g,'$1 days'] ]:[ [/^Hello, (.+)\.$/,'Hola, $1.'], [/^(\d+) quotes received$/,'$1 cotizaciones recibidas'], [/^Quote: (.+)$/,'Cotizar: $1'], [/^Updated (.+)$/,'Actualizado $1'], [/^Report about (.+)$/,'Reporte sobre $1'], [/^Reported by @(.+)$/,'Reportado por @$1'], [/(\d+) days\b/g,'$1 días'] ];
    let next=value;for(const [matcher,replacement] of pairs)next=next.replace(matcher,replacement);return next;
  }
  function translated(value,target=language){const clean=normalize(value);const key=aliases.get(clean);if(key)return dictionary[key][target];return pattern(clean,target)}
  function translateText(node){if(!node.nodeValue||['SCRIPT','STYLE','NOSCRIPT'].includes(node.parentElement?.tagName))return;const raw=node.nodeValue;const clean=normalize(raw);if(!clean)return;const next=translated(clean);if(next===clean)return;const lead=raw.match(/^\s*/)?.[0]||'';const tail=raw.match(/\s*$/)?.[0]||'';node.nodeValue=`${lead}${next}${tail}`}
  function translateAttribute(element,name){if(!element.hasAttribute(name))return;const raw=element.getAttribute(name);const next=translated(raw);if(next!==normalize(raw))element.setAttribute(name,next)}
  function translateRoot(root=document.documentElement){
    if(root.nodeType===Node.TEXT_NODE)return translateText(root);
    const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode()))translateText(node);
    if(root.nodeType===Node.ELEMENT_NODE)for(const name of ['placeholder','aria-label','title','content'])translateAttribute(root,name);
    root.querySelectorAll?.('[placeholder],[aria-label],[title],meta[content]').forEach(element=>{for(const name of ['placeholder','aria-label','title','content'])translateAttribute(element,name)});
  }
  function updateSwitcher(){document.querySelectorAll('.language-switcher button').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.language===language)))}
  function setLanguage(next){language=next==='en'?'en':'es';localStorage.setItem('cm_language',language);const url=new URL(location.href);url.searchParams.set('lang',language);history.replaceState(null,'',`${url.pathname}${url.search}${url.hash}`);document.documentElement.lang=language;translateRoot();updateSwitcher();window.dispatchEvent(new CustomEvent('construmatch:language',{detail:{language}}))}
  function createSwitcher(){if(document.querySelector('.language-switcher'))return;const control=document.createElement('div');control.className='language-switcher';control.setAttribute('role','group');control.setAttribute('aria-label','Idioma / Language');control.innerHTML='<button type="button" data-language="es">ES</button><button type="button" data-language="en">EN</button>';control.addEventListener('click',event=>{const button=event.target.closest('[data-language]');if(button)setLanguage(button.dataset.language)});document.body.append(control);updateSwitcher()}
  document.documentElement.lang=language;translateRoot();createSwitcher();
